// Runtime config: window.SORAPLAN_CONFIG (public/config.js, generated by deploy/deploy.sh)
// with Vite env overrides for local development (web/.env.local).

interface RuntimeConfig {
  API_BASE_URL?: string;
  CATALOG_BASE_URL?: string;
  FIREBASE?: { apiKey?: string; authDomain?: string; projectId?: string; appId?: string };
}

declare global {
  interface Window {
    SORAPLAN_CONFIG?: RuntimeConfig;
  }
}

const runtime: RuntimeConfig = (typeof window !== "undefined" && window.SORAPLAN_CONFIG) || {};
const env = import.meta.env;

export const config = {
  apiBaseUrl: (env.VITE_API_BASE_URL || runtime.API_BASE_URL || "http://localhost:8000/v1").replace(/\/$/, ""),
  catalogBaseUrl: (runtime.CATALOG_BASE_URL || "https://storage.googleapis.com/soraplan-catalog").replace(/\/$/, ""),
  firebase: {
    apiKey: env.VITE_FIREBASE_API_KEY || runtime.FIREBASE?.apiKey || "",
    authDomain: runtime.FIREBASE?.authDomain || "soraplan.firebaseapp.com",
    projectId: runtime.FIREBASE?.projectId || "soraplan",
    ...(runtime.FIREBASE?.appId ? { appId: runtime.FIREBASE.appId } : {}),
  },
};

/** Public URL of a catalog object; logical paths look like assets/{Style}/{file}. */
export function catalogUrl(path: string | null | undefined): string | null {
  if (!path) return null;
  if (/^https?:\/\//.test(path)) return path;
  return `${config.catalogBaseUrl}/${path.replace(/^\//, "")}`;
}
